:root{
  --bg:var(--appsmith-theme-backgroundColor,#0f172a);
  --surface:var(--appsmith-theme-surfaceColor,#0f172a);
  --card:var(--appsmith-theme-cardColor,#1e293b);
  --alt:var(--appsmith-theme-surfaceAltColor,#1e293b);
  --hover:var(--appsmith-theme-surfaceHoverColor,#26344b);
  --line:var(--appsmith-theme-borderColor,#334155);
  --line2:var(--appsmith-theme-borderMidColor,#475569);
  --strong:var(--appsmith-theme-textStrongColor,#ffffff);
  --text:var(--appsmith-theme-textColor,#e2e8f0);
  --soft:var(--appsmith-theme-textSecondaryColor,#94a3b8);
  --muted:var(--appsmith-theme-textMutedColor,#64748b);
  --link:var(--appsmith-theme-linkColor,#60a5fa);
  --action:var(--appsmith-theme-actionColor,#2563eb);
  --danger:var(--appsmith-theme-dangerColor,#f87171);
  --ok:var(--appsmith-theme-successColor,#34d399);
  --warn:var(--appsmith-theme-warningColor,#fbbf24);
}
*{box-sizing:border-box}
/* native controls (date picker icon) follow the theme */
:root[data-scheme=dark]{color-scheme:dark}
:root[data-scheme=light]{color-scheme:light}
/* the widget grows to its content (auto height) so only the page scrolls */
html,body{margin:0;background:var(--surface);color:var(--text);font-family:"Open Sans","Inter","Segoe UI",Arial,sans-serif;font-size:14px;overflow:hidden}
/* one spacing for the outer edges and the gap between builder and rules list */
.shell{--gap:16px;display:grid;grid-template-columns:minmax(0,1fr) 250px;column-gap:var(--gap);padding:0 var(--gap);align-items:start;width:100%}
.nav{order:2;margin:0 0 20px;padding:14px 10px;display:flex;flex-direction:column;gap:2px;background:var(--card);border:1px solid var(--line);border-radius:10px;min-width:0}
.nav-h{font-size:12px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--soft);padding:2px 12px 10px}
.nav-i{display:block;padding:9px 12px;border-radius:6px;color:var(--text);cursor:pointer;border-left:3px solid transparent;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.nav-i:hover{background:var(--hover)}
.nav-i.on{background:color-mix(in srgb,var(--action) 16%,transparent);border-left-color:var(--action);color:var(--strong);font-weight:700}
.nav-sep{height:1px;background:var(--line);margin:8px 12px}
/* the rule title spans both columns, so the first card and the rules card start level */
.shell-title{grid-column:1/-1;padding:20px 0 16px}
.page{padding:0 0 40px;display:flex;flex-direction:column;gap:16px;width:100%;min-width:0}
/* room below an open dropdown, so the widget grows instead of cutting it off */
.page:has(.pop){padding-bottom:340px}
h1{margin:0 0 4px;font-size:18px;color:var(--strong)}
h2{margin:0;font-size:16px;color:var(--strong)}
.title-row,.card-head,.alias-head,.group-head,.bar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.grow{flex:1}
.muted{color:var(--soft)}
.small{font-size:12.5px}
.pad{padding:18px 4px}
.pad-s{padding:10px 8px}
.hint{margin:2px 0 4px}
.err{color:var(--danger)}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12.5px}
.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px 18px;display:flex;flex-direction:column;gap:10px;min-width:0}
.card-head{margin-bottom:4px}

/* inputs and the shared dropdown look the same */
.inp{height:36px;border:1px solid var(--line2);border-radius:6px;background:var(--surface);color:var(--text);padding:0 10px;font:inherit;min-width:0;width:100%}
.inp:focus,.inp:focus-visible{outline:2px solid var(--action);outline-offset:-1px}
.inp:disabled{opacity:.5;cursor:default}
.inp::placeholder{color:var(--muted)}
.inp.date{width:150px}
.sel{position:relative;min-width:0;width:100%}
.sel-btn{display:flex;align-items:center;gap:8px;text-align:left;cursor:pointer}
.sel-btn.ph .sel-txt{color:var(--muted)}
.sel-txt{flex:1;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.chev{color:var(--muted);font-size:12px}
.pop{position:absolute;z-index:20;top:40px;left:0;min-width:100%;width:max-content;max-width:520px;background:var(--card);border:1px solid var(--line2);border-radius:8px;box-shadow:0 12px 32px color-mix(in srgb,var(--strong) 18%,transparent);padding:6px;display:flex;flex-direction:column;gap:6px}
.pop-list{max-height:280px;overflow:auto;display:flex;flex-direction:column}
.pop-row{display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:5px;cursor:pointer;color:var(--text);white-space:nowrap}
.pop-row.hi,.pop-row:hover{background:var(--hover)}
.pop-row.on{color:var(--strong);font-weight:700}
.pop-row.on::after{content:"✓";margin-left:auto;color:var(--action)}
.pop-row input{margin:0}
.pop-acts{display:flex;justify-content:space-between;font-size:12.5px;padding:0 4px}
.pop-acts a{color:var(--link);cursor:pointer}
.cnt{margin-left:auto;padding-left:14px;color:var(--muted);font-size:12px}
.pop-row.on .cnt{margin-left:auto}
.w-sm{width:150px}
.w-match{width:220px}
.w-mode{width:240px}
.w-preset{width:340px}

/* rows */
.row.chg{grid-template-columns:minmax(140px,.8fr) minmax(140px,.8fr) minmax(140px,.8fr) minmax(180px,1.8fr) 32px}
.chg-note{grid-column:span 1}
.chg-list{display:flex;flex-direction:column;gap:10px}
.row.chg-basic{grid-template-columns:minmax(150px,.8fr) minmax(150px,.8fr) minmax(220px,1.8fr) 32px}
.adv{display:inline-flex;align-items:center;gap:8px;padding:7px 12px;border:1px solid var(--line2);border-radius:999px;color:var(--text);cursor:pointer;font-weight:600;user-select:none}
.adv input{margin:0;accent-color:var(--action);cursor:pointer}
.adv.locked{opacity:.7;cursor:default}
.adv.locked input{cursor:default}
.row{display:grid;grid-template-columns:64px minmax(150px,1.1fr) minmax(130px,.8fr) minmax(180px,1.8fr) 32px;gap:10px;align-items:center}
.row-wrap{display:grid;grid-template-columns:64px 1fr;gap:10px;align-items:start}
.lead{display:inline-flex;justify-content:center;align-items:center;height:32px;border-radius:6px;background:var(--alt);border:1px solid var(--line);color:var(--soft);font-weight:700;font-size:12.5px}
.lead.to{width:40px;flex:none}
.val{display:flex;gap:8px;align-items:center;min-width:0}
.val>.inp,.val>.sel{flex:1}
.val-empty{min-height:36px}
.mode{height:36px;padding:0 9px;border-radius:6px;border:1px dashed var(--line2);background:transparent;color:var(--soft);font:inherit;font-size:12px;cursor:pointer;white-space:nowrap;flex:none}
.mode:hover{color:var(--strong);border-color:var(--soft)}
.x{width:32px;height:32px;border:0;border-radius:6px;background:transparent;color:var(--muted);font-size:20px;line-height:1;cursor:pointer}
.x:hover{background:var(--hover);color:var(--danger)}
.group-root{display:flex;flex-direction:column;gap:10px}
.group{border:1px dashed var(--line2);border-radius:8px;padding:10px 12px;display:flex;flex-direction:column;gap:10px;background:transparent}
.adds{display:flex;gap:10px;flex-wrap:wrap}

/* buttons */
.btn{height:36px;padding:0 14px;border-radius:6px;font:inherit;font-weight:600;cursor:pointer;border:1px solid var(--line2);background:transparent;color:var(--text);white-space:nowrap}
.btn.sm{height:32px;padding:0 12px;font-size:13px}
.btn.ghost:hover{background:var(--hover)}
.btn.danger{color:var(--danger);border-color:transparent}
.btn.danger:hover{border-color:var(--danger)}
.btn.primary{background:var(--action);border-color:var(--action);color:#fff}
.btn.primary:disabled{opacity:.55;cursor:default}

.alias{border:1px solid var(--line);border-radius:8px;padding:12px;display:flex;flex-direction:column;gap:10px;background:var(--surface)}
.badge{display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:6px;background:var(--action);color:#fff;font-weight:800}
.pill{padding:3px 10px;border-radius:999px;background:var(--alt);border:1px solid var(--line);color:var(--soft);font-size:12.5px}
.bar{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 14px}
.dot{width:9px;height:9px;border-radius:50%;background:var(--ok);display:inline-block}
.dot.bad{background:var(--danger)}
.dot.warn{background:var(--warn);margin-right:6px;vertical-align:middle}
.sql{margin:0;padding:14px;border-radius:8px;background:var(--surface);border:1px solid var(--line);color:var(--soft);white-space:pre-wrap;word-break:break-word;font-family:ui-monospace,Menlo,monospace;font-size:12px}

/* results */
.tabs{display:flex;gap:4px;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:3px}
.tab{height:30px;padding:0 12px;border:0;border-radius:6px;background:transparent;color:var(--soft);font:inherit;font-weight:600;cursor:pointer}
.tab.on{background:var(--action);color:#fff}
.tbl-wrap{max-width:100%;overflow-x:auto;overflow-y:hidden;border:1px solid var(--line);border-radius:8px}
.tbl{width:100%;border-collapse:collapse}
.tbl th{position:sticky;top:0;background:var(--alt);text-align:left;padding:10px 14px;color:var(--soft);font-size:12.5px;font-weight:700;white-space:nowrap;border-bottom:1px solid var(--line)}
.tbl td{padding:9px 14px;border-bottom:1px solid var(--line);white-space:nowrap;max-width:280px;overflow:hidden;text-overflow:ellipsis}
.tbl tr:hover td{background:var(--hover)}
.num{text-align:right}
.link{color:var(--link);cursor:pointer;font-weight:600}
.link:hover{text-decoration:underline}
.gone{display:inline-block;padding:2px 8px;border-radius:5px;background:color-mix(in srgb,var(--danger) 16%,transparent);color:var(--danger);font-weight:700}
.new{display:inline-block;padding:2px 8px;border-radius:5px;background:color-mix(in srgb,var(--ok) 16%,transparent);color:var(--ok);font-weight:700}
@media (max-width:900px){.shell{grid-template-columns:1fr}.nav{order:0;flex-direction:row;flex-wrap:wrap;margin:0 0 16px}.nav-h,.nav-sep{display:none}.row{grid-template-columns:56px 1fr 1fr}.row .val,.row .val-empty{grid-column:2/4}.row .x{grid-column:3;justify-self:end}.w-preset,.w-match,.w-mode{width:100%}}
/* ---- mockup rule pages ---- */
.view{display:flex;flex-direction:column;gap:16px}
.dates{display:inline-flex;align-items:center;gap:8px}
.card-actions{display:flex;align-items:center;gap:10px;margin-top:4px}
.add-link{color:var(--link);font-weight:700;cursor:pointer}
.add-link:hover{text-decoration:underline}
.subcard{border:1px solid var(--line);border-radius:8px;padding:12px 14px;display:flex;flex-direction:column;gap:10px;background:var(--surface)}
.sub-h{font-weight:700;color:var(--strong)}
.checks{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px 16px}
.chk{display:flex;align-items:center;gap:8px;cursor:pointer;min-width:0}
.chk span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.chk input,.radio input{accent-color:var(--action);margin:0}
.target-row{display:flex;align-items:center;gap:12px}
.pill-blue{padding:4px 12px;border-radius:6px;font-weight:700;font-size:13px;color:var(--link);background:color-mix(in srgb,var(--link) 14%,transparent)}
.pill-green{padding:4px 12px;border-radius:6px;font-weight:700;font-size:13px;color:var(--ok);background:color-mix(in srgb,var(--ok) 14%,transparent)}
.row.chg-mock{grid-template-columns:minmax(140px,.7fr) minmax(170px,1fr) 48px minmax(220px,1.6fr) 32px}
.lead.to{width:auto}
.steps{display:flex;align-items:center;gap:12px}
.step{display:flex;align-items:center;gap:10px;color:var(--soft);font-weight:700;flex:1}
.step:not(:last-child)::after{content:"";flex:1;height:1px;background:var(--line2)}
.step-n{width:30px;height:30px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;background:var(--alt);color:var(--soft);flex:none}
.step.on{color:var(--link)}
.step.on .step-n,.step.done .step-n{background:var(--action);color:#fff}
.ptbl td{white-space:nowrap}
.chip{display:inline-block;padding:2px 10px;border-radius:5px;background:var(--alt);font-family:ui-monospace,Menlo,monospace;font-size:12.5px}
.arrow{color:var(--soft);text-align:center;width:40px}
.strong{font-weight:800}
.row.pair{grid-template-columns:48px minmax(150px,1fr) minmax(130px,.8fr) minmax(170px,1.3fr) minmax(130px,.7fr) 32px}
.lead.letter{background:color-mix(in srgb,var(--link) 16%,transparent);color:var(--link);border-color:transparent;font-size:14px}
.letter-sel{width:48px}
.rules2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;align-items:start}
.card.rule{gap:12px}
.iff{display:grid;grid-template-columns:56px repeat(3,minmax(0,1fr));gap:8px;align-items:center}
.iff.then{grid-template-columns:56px repeat(2,minmax(0,1fr))}
.iff .lead{color:var(--link);background:color-mix(in srgb,var(--link) 12%,transparent);border-color:transparent}
.danger-sel .sel-btn{border-color:var(--danger);color:var(--danger);font-weight:700;background:color-mix(in srgb,var(--danger) 8%,transparent)}
.good-sel .sel-btn{border-color:var(--ok);background:color-mix(in srgb,var(--ok) 10%,transparent)}
.example{border:1px solid var(--line);border-radius:8px;overflow:hidden}
.ex-h{padding:10px 14px;font-weight:800;color:var(--strong);background:var(--alt)}
.ex-body{display:grid;grid-template-columns:1fr 32px 1fr;gap:10px;padding:12px 14px;align-items:center}
.ex-k{font-weight:700;color:var(--soft);margin-bottom:6px}
.ex-line{display:flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:6px;padding:6px 10px;margin-bottom:6px}
.ex-line.struck{border-color:transparent;background:color-mix(in srgb,var(--danger) 14%,transparent);color:var(--danger)}
.ex-line.after{border-color:transparent;background:color-mix(in srgb,var(--ok) 14%,transparent);font-weight:700}
.strike{text-decoration:line-through}
.minus{display:inline-flex;width:18px;height:18px;border-radius:50%;background:var(--danger);color:#fff;align-items:center;justify-content:center;font-weight:800;line-height:1}
.ex-v{margin-left:auto;font-variant-numeric:tabular-nums}
.ex-arrow{color:var(--soft);text-align:center;font-size:18px}
.info{display:flex;align-items:center;gap:10px;padding:12px 16px;border:1px solid var(--line);border-radius:10px;background:color-mix(in srgb,var(--link) 8%,var(--card))}
.info-i{width:22px;height:22px;border-radius:50%;border:2px solid var(--link);color:var(--link);display:inline-flex;align-items:center;justify-content:center;font-weight:800;font-size:12px}
.badge-st{padding:3px 10px;border-radius:6px;font-weight:700;font-size:13px}
.badge-st.ok{color:var(--ok);background:color-mix(in srgb,var(--ok) 16%,transparent)}
.badge-st.need{color:var(--warn);background:color-mix(in srgb,var(--warn) 18%,transparent)}
.ctbl td{padding:6px 10px;overflow:visible;max-width:none}
.ctbl .sel{min-width:180px}
.tbl-wrap:has(.ctbl){overflow:visible}
.dd{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,1fr);gap:20px;align-items:start}
.row.dd-row{grid-template-columns:110px minmax(160px,1fr) minmax(120px,.6fr)}
.dd-pick{border:1px solid var(--line);border-radius:8px;padding:12px 14px;display:flex;flex-direction:column;gap:10px}
.radio{display:flex;align-items:center;gap:10px;cursor:pointer}
.foot{display:flex;align-items:center;gap:12px;padding:14px 16px;border-top:1px solid var(--line);background:var(--card);border-radius:10px;border:1px solid var(--line)}
.foot-txt{color:var(--text)}
.foot .dot{background:var(--ok)}
.foot .dot.warn{background:var(--warn)}
@media (max-width:1100px){.rules2,.dd{grid-template-columns:1fr}.checks{grid-template-columns:repeat(2,minmax(0,1fr))}}
.res-body{display:flex;flex-direction:column;gap:10px}
.foot-wrap{display:flex;flex-direction:column;gap:12px}

