.lead.letter{background:color-mix(in srgb,var(--link) 16%,transparent);color:var(--link);border-color:transparent;font-size:14px}
.letter-sel{width:48px}
.rules2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;align-items:start}
