.iff .lead{color:var(--link);background:color-mix(in srgb,var(--link) 12%,transparent);border-color:transparent}
.danger-sel .sel-btn{border-color:var(--danger);color:var(--danger);font-weight:700;background:color-mix(in srgb,var(--danger) 8%,transparent)}
.good-sel .sel-btn{border-color:var(--ok);background:color-mix(in srgb,var(--ok) 10%,transparent)}
.example{border:1px solid var(--line);border-radius:8px;overflow:hidden}
.ex-h{padding:10px 14px;font-weight:800;color:var(--strong);background:var(--alt)}
.ex-body{display:grid;grid-template-columns:1fr 32px 1fr;gap:10px;padding:12px 14px;align-items:center}
.ex-k{font-weight:700;color:var(--soft);margin-bottom:6px}
.ex-line{display:flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:6px;padding:6px 10px;margin-bottom:6px}
.ex-line.struck{border-color:transparent;background:color-mix(in srgb,var(--danger) 14%,transparent);color:var(--danger)}
.ex-line.after{border-color:transparent;background:color-mix(in srgb,var(--ok) 14%,transparent);font-weight:700}
.strike{text-decoration:line-through}
.minus{display:inline-flex;width:18px;height:18px;border-radius:50%;background:var(--danger);color:#fff;align-items:center;justify-content:center;font-weight:800;line-height:1}
.ex-v{margin-left:auto;font-variant-numeric:tabular-nums}
.ex-arrow{color:var(--soft);text-align:center;font-size:18px}
.info{display:flex;align-items:center;gap:10px;padding:12px 16px;border:1px solid var(--line);border-radius:10px;background:color-mix(in srgb,var(--link) 8%,var(--card))}
.info-i{width:22px;height:22px;border-radius:50%;border:2px solid var(--link);color:var(--link);display:inline-flex;align-items:center;justify-content:center;font-weight:800;font-size:12px}
.badge-st{padding:3px 10px;border-radius:6px;font-weight:700;font-size:13px}
.badge-st.ok{color:var(--ok);background:color-mix(in srgb,var(--ok) 16%,transparent)}
.badge-st.need{color:var(--warn);background:color-mix(in srgb,var(--warn) 18%,transparent)}
.ctbl td{padding:6px 10px;overflow:visible;max-width:none}
.ctbl .sel{min-width:180px}
.tbl-wrap:has(.ctbl){overflow:visible}
.dd{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,1fr);gap:20px;align-items:start}
.row.dd-row{grid-template-columns:110px minmax(160px,1fr) minmax(120px,.6fr)}
.dd-pick{border:1px solid var(--line);border-radius:8px;padding:12px 14px;display:flex;flex-direction:column;gap:10px}
.radio{display:flex;align-items:center;gap:10px;cursor:pointer}
.foot{display:flex;align-items:center;gap:12px;padding:14px 16px;border-top:1px solid var(--line);background:var(--card);border-radius:10px;border:1px solid var(--line)}
.foot-txt{color:var(--text)}
.foot .dot{background:var(--ok)}
.foot .dot.warn{background:var(--warn)}
@media (max-width:1100px){.rules2,.dd{grid-template-columns:1fr}.checks{grid-template-columns:repeat(2,minmax(0,1fr))}}
.res-body{display:flex;flex-direction:column;gap:10px}
.foot-wrap{display:flex;flex-direction:column;gap:12px}

