function defaultDates() {
  const to = new Date(); const from = new Date(); from.setFullYear(from.getFullYear() - 1);
  return { dateFrom: iso(from), dateTo: iso(to) };
}
const blankRule = () => Object.assign({ key: "custom", match: "ALL", conditions: [], aliases: [], cross: [], changes: [] }, defaultDates());
const newCond = field => ({ id: uid(), field: field || "", op: "", value: "", mode: "value", valueField: "" });
/* fields a change can set */
const CHANGE_FIELDS = [{ id: "uom", label: "Unit of measure" }, { id: "code", label: "Observation type" }, { id: "description", label: "Description" }];
const ACTIONS = [{ value: "set", label: "Set field" }, { value: "remove", label: "Remove line" }];
const BASIC_ACTIONS = [{ value: "set", label: "Set field" }, { value: "remove", label: "Remove the line" }];
const newChange = (target, p) => Object.assign({ id: uid(), target: target === undefined ? "A" : target, action: "set", field: "uom", value: "" }, p || {});
/* demand observation types: the Demand units mockup's 20, plus the demand codes
   seen in the line items data (BILLEDDEM_USE, GENDEM_*, INFO_GENDEM_USE) */
const DEMAND_CODES = ["BILLEDDEM_MIDPEAK", "BILLEDDEM_OFFPEAK", "BILLEDDEM_ONPEAK", "BILLEDDEM_SHDPEAK", "BILLEDDEM_SUPER",
  "BILLEDGENDEM_USE", "DEM_USE", "DEM_ONPEAK", "DEM_MIDPEAK", "DEM_OFFPEAK", "DEM_SHDPEAK", "DEM_SUPPEAK", "DEM_SUPOFFPEAK",
  "CRFDEM_USE", "INFO_DEMAND", "DEM_CHG", "BILLEDREACTDEM_USE", "REACTDEM_OFFPK", "REACTDEM_ONPK", "REACT_DEM",
  "BILLEDDEM_USE", "GENDEM_USE", "GENDEM_ONPEAK", "GENDEM_MIDPEAK", "GENDEM_OFFPEAK", "INFO_GENDEM_USE"];
const MATCH_OPTS = [{ value: "ALL", label: "Match ALL conditions" }, { value: "ANY", label: "Match ANY condition" }];
const GROUP_MATCH_OPTS = [{ value: "ALL", label: "ALL of these" }, { value: "ANY", label: "ANY of these" }];
const cond = (field, op, value, extra) => Object.assign(newCond(field), { op, value }, extra || {});
const MODE_OPTS = [{ value: "exists", label: "must exist on the bill" }, { value: "not_exists", label: "must NOT exist on the bill" }];

/* rebuild ids on a rule loaded from the store */
function withIds(r) {
  const fix = n => n.conditions ? Object.assign({}, n, { id: uid(), conditions: n.conditions.map(fix) }) : Object.assign({}, n, { id: uid() });
  const out = fix(Object.assign(blankRule(), r || {}));
  out.aliases = (r && r.aliases || []).map(a => Object.assign({ match: "ALL" }, a, { id: uid(), conditions: (a.conditions || []).map(fix) }));
  out.cross = (r && r.cross || []).map(fix);
  out.changes = (r && r.changes || []).map(c => Object.assign({}, c, { id: uid() }));
  return out;
}

function useModel() {
  const [m, setM] = useState(appsmith.model || {});
  useEffect(() => {
    const up = () => setM(Object.assign({}, appsmith.model || {}));
    up();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(up);
    const t = setInterval(up, 500);
    return () => clearInterval(t);
  }, []);
  return m;
}

function useOutside(ref, onOut) {
  useEffect(() => {
    const h = e => { if (ref.current && !ref.current.contains(e.target)) onOut(); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);
}

/* ---------- one dropdown for everything: themed, searchable ---------- */

/* options: [{ value, label, count? }]. free: typed text can be used as the value. */
function Select({ value, options, onChange, placeholder, disabled, search, free, className, mono }) {
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState("");
  const [hi, setHi] = useState(0);
  const ref = useRef(null);
  const listRef = useRef(null);
  useOutside(ref, () => setOpen(false));
  const canSearch = search !== undefined ? search : (free || options.length > 8);
  const cur = options.find(o => o.value === value);
  const label = cur ? cur.label : (value !== "" && value != null ? String(value) : "");
  const needle = q.trim().toLowerCase();
  const exact = o => String(o.value).toLowerCase() === needle || String(o.label).toLowerCase() === needle;
  // an exact match goes first, so typing "KW" + Enter picks KW, not KWH
  const shown = !needle ? options : options.filter(o => (o.label + " " + o.value).toLowerCase().includes(needle))
    .sort((a, b) => exact(b) - exact(a));
  const useTyped = free && q.trim() && !options.some(o => o.value === q.trim());
  const rows = (useTyped ? [{ value: q.trim(), label: "Use “" + q.trim() + "”", typed: true }] : []).concat(shown.slice(0, 500));
  const pick = o => { onChange(o.value); setOpen(false); setQ(""); };
  const toggle = () => { if (disabled) return; setOpen(!open); setQ(""); setHi(Math.max(0, options.findIndex(o => o.value === value))); };
  const key = e => {
    if (e.key === "ArrowDown") { e.preventDefault(); setHi(Math.min(hi + 1, rows.length - 1)); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setHi(Math.max(hi - 1, 0)); }
    else if (e.key === "Enter") { e.preventDefault(); if (rows[hi]) pick(rows[hi]); }
    else if (e.key === "Escape") setOpen(false);
  };
  useEffect(() => {
    const el = listRef.current && listRef.current.children[hi];
    if (el && el.scrollIntoView) el.scrollIntoView({ block: "nearest" });
  }, [hi, open]);
  return html`<div className=${"sel " + (className || "")} ref=${ref}>
    <button type="button" className=${"inp sel-btn" + (label ? "" : " ph") + (mono ? " mono" : "")} disabled=${disabled}
      onClick=${toggle} onKeyDown=${e => { if (!open && (e.key === "ArrowDown" || e.key === "Enter")) { e.preventDefault(); toggle(); } else if (open) key(e); }}>
      <span className="sel-txt">${label || placeholder || "Choose…"}</span><span className="chev">▾</span>
    </button>
    ${open && html`<div className="pop">
      ${canSearch && html`<input className="inp" autoFocus placeholder=${free ? "Search or type a value" : "Search"} value=${q}
        onInput=${e => { setQ(e.target.value); setHi(0); }} onKeyDown=${key} />`}
      <div className="pop-list" ref=${listRef}>
        ${rows.map((o, i) => html`<div key=${(o.typed ? "~" : "") + o.value} className=${"pop-row" + (i === hi ? " hi" : "") + (o.value === value ? " on" : "")}
            onMouseEnter=${() => setHi(i)} onMouseDown=${e => { e.preventDefault(); pick(o); }}>
          <span className=${mono && !o.typed ? "mono" : ""}>${o.label}</span>${o.count != null && html`<span className="cnt">${o.count.toLocaleString()}</span>`}
        </div>`)}
        ${!rows.length && html`<div className="muted pad-s">No matches</div>`}
      </div>
    </div>`}
  </div>`;
}

function MultiPick({ options, value, onChange }) {
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState("");
  const ref = useRef(null);
  useOutside(ref, () => setOpen(false));
  const sel = Array.isArray(value) ? value : [];
  const shown = options.filter(o => !q || o.value.toLowerCase().includes(q.toLowerCase()));
  const typed = q.trim() && !options.some(o => o.value === q.trim()) && !sel.includes(q.trim()) ? q.trim() : "";
  const toggle = v => onChange(sel.includes(v) ? sel.filter(x => x !== v) : sel.concat([v]));
  const label = !sel.length ? "" : sel.length <= 2 ? sel.join(", ") : sel.length + " selected";
  return html`<div className="sel" ref=${ref}>
    <button type="button" className=${"inp sel-btn" + (sel.length ? "" : " ph")} onClick=${() => setOpen(!open)}>
      <span className="sel-txt">${label || "Choose values…"}</span><span className="chev">▾</span></button>
    ${open && html`<div className="pop">
      <input className="inp" placeholder="Search or type a value" value=${q} onInput=${e => setQ(e.target.value)} autoFocus
        onKeyDown=${e => { if (e.key === "Enter" && typed) { e.preventDefault(); toggle(typed); setQ(""); } }} />
      <div className="pop-acts">
        <a onClick=${() => onChange(Array.from(new Set(sel.concat(shown.map(o => o.value)))))}>Select shown (${shown.length})</a>
        <a onClick=${() => onChange([])}>Clear</a>
      </div>
      <div className="pop-list">
        ${typed && html`<label className="pop-row"><input type="checkbox" checked=${false} onChange=${() => { toggle(typed); setQ(""); }} /><span>Add “${typed}”</span></label>`}
        ${sel.filter(v => !options.some(o => o.value === v)).map(v => html`<label key=${"x" + v} className="pop-row">
          <input type="checkbox" checked=${true} onChange=${() => toggle(v)} /><span className="mono">${v}</span></label>`)}
        ${shown.slice(0, 500).map(o => html`<label key=${o.value} className="pop-row">
          <input type="checkbox" checked=${sel.includes(o.value)} onChange=${() => toggle(o.value)} />
          <span className="mono">${o.value}</span><span className="cnt">${o.n.toLocaleString()}</span></label>`)}
        ${!shown.length && !typed && html`<div className="muted pad-s">No values</div>`}
      </div>
    </div>`}
  </div>`;
}

const asOpts = vals => vals.map(o => ({ value: o.value, label: o.value, count: o.n }));

function ValueEditor({ c, f, options, compareFields, onChange }) {
  if (!f || !c.op || NOVAL.includes(c.op)) return html`<div className="val-empty"></div>`;
  const set = p => onChange(Object.assign({}, c, p));
  const canField = CMP.includes(c.op) && compareFields.length > 0;
  const modeBtn = canField && html`<button type="button" className="mode" title="Compare with a value or with another field"
      onClick=${() => set({ mode: c.mode === "field" ? "value" : "field", value: "", valueField: "" })}>${c.mode === "field" ? "field" : "value"}</button>`;
  if (c.mode === "field" && canField) {
    return html`<div className="val">${modeBtn}
      <${Select} value=${c.valueField} placeholder="Choose field…" search=${true}
        options=${compareFields.map(x => ({ value: x.ref, label: x.label }))} onChange=${v => set({ valueField: v })} /></div>`;
  }
  const inType = f.type === "number" ? "number" : f.type === "date" ? "date" : "text";
  if (c.op === "in" || c.op === "not_in") {
    return html`<div className="val"><${MultiPick} options=${options} value=${c.value} onChange=${v => set({ value: v })} /></div>`;
  }
  if (c.op === "between") {
    const v = Array.isArray(c.value) ? c.value : ["", ""];
    return html`<div className="val two">
      <input className="inp" type=${inType} value=${v[0] || ""} onInput=${e => set({ value: [e.target.value, v[1] || ""] })} />
      <span className="muted">and</span>
      <input className="inp" type=${inType} value=${v[1] || ""} onInput=${e => set({ value: [v[0] || "", e.target.value] })} /></div>`;
  }
  if (inType === "text" && options.length && (c.op === "eq" || c.op === "neq")) {
    return html`<div className="val">${modeBtn}
      <${Select} value=${Array.isArray(c.value) ? "" : c.value} placeholder="Choose a value…" free=${true} mono=${true}
        options=${asOpts(options)} onChange=${v => set({ value: v })} /></div>`;
  }
  return html`<div className="val">${modeBtn}
    <input className="inp" type=${inType} placeholder="Enter value" value=${Array.isArray(c.value) ? "" : c.value}
      onInput=${e => set({ value: e.target.value })} /></div>`;
}

/* ---------- condition rows and groups ---------- */

function CondRow({ c, lead, fieldList, ctx, onChange, onRemove, fieldMode }) {
  const f = ctx.fieldOf(c.field);
  const ops = f ? ctx.ops[f.type] : [];
  const set = p => onChange(Object.assign({}, c, p));
  const compareFields = f ? fieldList.filter(x => x.ref !== c.field && kind(x.f.type) === kind(f.type)) : [];
  return html`<div className="row">
    <span className="lead">${lead}</span>
    <${Select} value=${c.field} placeholder="Choose field…" search=${true}
      options=${fieldList.map(x => ({ value: x.ref, label: x.label }))}
      onChange=${v => { const nf = ctx.fieldOf(v); set({ field: v, op: nf ? ctx.ops[nf.type][0] : "", value: "", mode: fieldMode ? "field" : "value", valueField: "" }); }} />
    <${Select} value=${c.op} placeholder="Operator" disabled=${!f} search=${false}
      options=${ops.map(o => ({ value: o, label: ctx.opLabels[o] }))}
      onChange=${op => {
        const multi = op === "in" || op === "not_in", two = op === "between";
        const was = c.op === "in" || c.op === "not_in" || c.op === "between";
        set({ op, value: multi ? [] : two ? ["", ""] : was ? "" : c.value, mode: CMP.includes(op) ? c.mode : "value" });
      }} />
    <${ValueEditor} c=${c} f=${f} options=${f && f.options ? (ctx.values[f.options] || []) : []} compareFields=${compareFields} onChange=${onChange} />
    <button type="button" className="x" title="Remove condition" onClick=${onRemove}>×</button>
  </div>`;
}

function Group({ node, depth, fieldList, ctx, onChange, onRemove, defaultField, firstLead }) {
  const kids = node.conditions || [];
  const setKids = k => onChange(Object.assign({}, node, { conditions: k }));
  const joiner = node.match === "ANY" ? "OR" : "AND";
  const fresh = () => {
    const c = newCond(defaultField);
    const f = ctx.fieldOf(defaultField);
    if (f) c.op = ctx.ops[f.type][0];
    return c;
  };
  return html`<div className=${depth ? "group" : "group-root"}>
    ${depth > 0 && html`<div className="group-head">
      <span className="muted small">Group: match</span>
      <${Select} className="w-sm" value=${node.match} search=${false} options=${GROUP_MATCH_OPTS}
        onChange=${v => onChange(Object.assign({}, node, { match: v }))} />
      <span className="grow"></span>
      <button type="button" className="btn ghost danger sm" onClick=${onRemove}>Remove group</button></div>`}
    ${kids.map((k, i) => k.conditions
      ? html`<div key=${k.id} className="row-wrap"><span className="lead">${i ? joiner : firstLead || "Where"}</span>
          <${Group} node=${k} depth=${depth + 1} fieldList=${fieldList} ctx=${ctx} defaultField=${defaultField}
            onChange=${nk => setKids(kids.map(x => x.id === k.id ? nk : x))} onRemove=${() => setKids(kids.filter(x => x.id !== k.id))} /></div>`
      : html`<${CondRow} key=${k.id} c=${k} lead=${i ? joiner : firstLead || "Where"} fieldList=${fieldList} ctx=${ctx}
          onChange=${nk => setKids(kids.map(x => x.id === k.id ? nk : x))} onRemove=${() => setKids(kids.filter(x => x.id !== k.id))} />`)}
    <div className="adds">
      <button type="button" className="btn ghost sm" onClick=${() => setKids(kids.concat([fresh()]))}>+ Add condition</button>
      ${depth < 3 && html`<button type="button" className="btn ghost sm" onClick=${() => setKids(kids.concat([{ id: uid(), match: node.match === "ANY" ? "ALL" : "ANY", conditions: [fresh()] }]))}>+ Add group</button>`}
    </div>
  </div>`;
}

/* ---------- correction rules (Sunny's mockups, on the line-item codes) ---------- */

const RULES = [
  { key: "missing", nav: "Missing consumption", title: "Recover missing consumption",
    sub: "Find bills, define changes, then review the affected observations.",
    build: () => ({ aliases: [
      { name: "A", mode: "exists", match: "ALL", conditions: [cond("A.code", "eq", "BILLEDUSE_USE")] },
      { name: "B", mode: "not_exists", match: "ALL", conditions: [cond("B.code", "eq", "USE_USE")] }],
      changes: [newChange("A", { field: "code", value: "USE_USE" })] }) },
  { key: "dupgen", nav: "Duplicate generation", title: "Compare generation observations",
    sub: "Match two observations on the same bill and compare their values.",
    build: () => ({ aliases: [
      { name: "A", mode: "exists", match: "ALL", conditions: [cond("A.code", "eq", "GEN_USE"), cond("A.description", "eq", "Generation (U)")] },
      { name: "B", mode: "exists", match: "ALL", conditions: [cond("B.code", "eq", "GEN_USE"), cond("B.description", "eq", "Generation (UC)")] }],
      cross: [cond("A.usage", "eq", "", { mode: "field", valueField: "B.usage" })],
      changes: [newChange("A", { action: "remove" })] }) },
  { key: "constellation", nav: "Constellation adjustment", title: "Constellation adjustment",
    sub: "On Constellation bills, retype the generation observation that does not match.",
    build: () => ({ match: "ALL", conditions: [cond("bill.vendor", "contains", "Constellation")], aliases: [
      { name: "A", mode: "exists", match: "ALL", conditions: [cond("A.code", "eq", "GEN_USE"), cond("A.description", "eq", "Generation (U)")] },
      { name: "B", mode: "exists", match: "ALL", conditions: [cond("B.code", "eq", "GEN_USE"), cond("B.description", "eq", "Generation (UC)")] }],
      cross: [cond("A.usage", "neq", "", { mode: "field", valueField: "B.usage" })],
      changes: [newChange("B", { field: "description", value: "Adjustment (UC)" })] }) },
  { key: "peak", nav: "Peak usage mapping", title: "Update multiple observations",
    sub: "Define a separate action for each matched observation.",
    build: () => ({ aliases: [
      { name: "A", mode: "exists", match: "ALL", conditions: [cond("A.code", "eq", "USE_ONPEAK")] },
      { name: "B", mode: "exists", match: "ALL", conditions: [cond("B.code", "eq", "USE_OFFPEAK")] }],
      changes: [newChange("A", { field: "code", value: "BILLEDUSE_ONPEAK" }), newChange("B", { field: "code", value: "BILLEDUSE_OFFPEAK" })] }) },
  { key: "dupdem", nav: "Duplicate demand", title: "Remove duplicate demand",
    sub: "Choose which observation to remove. The other will be retained.",
    build: () => ({ aliases: [
      { name: "A", mode: "exists", match: "ALL", conditions: [cond("A.code", "eq", "BILLEDDEM_USE")] },
      { name: "B", mode: "exists", match: "ALL", conditions: [cond("B.code", "eq", "INFO_DEMAND")] }],
      changes: [newChange("", { action: "remove" })] }) },
  { key: "demand", nav: "Demand units", title: "Correct demand units",
    sub: "Find demand observations labeled kwh and choose the replacement unit.",
    build: values => {
      const codes = (values.code || []).map(o => o.value);
      const uoms = (values.uom || []).map(o => o.value);
      // the full list every time, so the rule stays the same when the customer changes
      const dem = DEMAND_CODES.concat(codes.filter(c => /DEM/i.test(c) && !DEMAND_CODES.includes(c)));
      const kwh = uoms.find(u => /^kwh$/i.test(u)) || "KWH";
      const kw = uoms.find(u => /^kw$/i.test(u)) || "KW";
      return { aliases: [{ name: "A", mode: "exists", match: "ALL", conditions: [cond("A.code", "in", dem), cond("A.uom", "eq", kwh)] }],
        changes: [newChange("A", { value: kw })] };
    } }
];
const CUSTOM = { key: "custom", nav: "Custom rule", title: "Find bills",
  sub: "Find bills by their own fields and by the lines on them." };
const ruleInfo = key => RULES.find(r => r.key === key) || CUSTOM;

/* Basic shows one list of conditions (bill fields and one line's fields) and
   changes to that line. Anything more needs Advanced. */
function needsAdvanced(r) {
  const groups = n => (n.conditions || []).some(k => k.conditions);
  return r.match === "ANY" || groups(r) || r.cross.length > 0 ||
    r.aliases.length > 1 || r.aliases.some(a => a.name !== "A" || a.mode === "not_exists" || (a.match || "ALL") === "ANY" || groups(a)) ||
    r.changes.some(c => c.target && c.target !== "A");
}

/* ---------- results ---------- */

const money = v => v == null || v === "" ? "" : Number(v).toLocaleString("en-US", { style: "currency", currency: "USD" });
const COLS = [
  { k: "bill_id", l: "Bill ID" }, { k: "statement_date", l: "Statement date" }, { k: "utility", l: "Utility" },
  { k: "vendor", l: "Vendor" }, { k: "account", l: "Account" }, { k: "location_name", l: "Location" },
  { k: "line_count", l: "Lines", num: true }, { k: "total_charges", l: "Line total", num: true, fmt: money }
];
const OBS_COLS = [
  { k: "bill_id", l: "Bill ID" }, { k: "statement_date", l: "Statement date" }, { k: "vendor", l: "Vendor" },
  { k: "code", l: "Observation type", mono: true }, { k: "uom", l: "UOM" }, { k: "usage", l: "Quantity", num: true },
  { k: "charge", l: "Charge", num: true, fmt: money }, { k: "description", l: "Description" }
];
function toCsv(cols, rows) {
  const q = v => { const s = v == null ? "" : String(v); return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
  return [cols.map(c => c.l).join(",")].concat(rows.map(r => cols.map(c => q(c.get ? c.get(r) : r[c.k])).join(","))).join("\n");
}
const cellText = (c, r) => c.fmt ? c.fmt(r[c.k]) : (r[c.k] == null ? "" : String(r[c.k]));

function Table({ cols, rows, keyOf }) {
  return html`<div className="tbl-wrap"><table className="tbl">
    <thead><tr>${cols.map(c => html`<th key=${c.k} className=${c.num ? "num" : ""}>${c.l}</th>`)}</tr></thead>
    <tbody>${rows.map((r, i) => html`<tr key=${keyOf(r, i)}>${cols.map(c => html`<td key=${c.k} className=${(c.num ? "num " : "") + (c.mono ? "mono" : "")}>${
      c.k === "bill_id" ? html`<a className="link" onClick=${() => appsmith.triggerEvent("onOpenBill", { billId: r.bill_id })}>${r.bill_id}</a>`
        : c.render ? c.render(r) : cellText(c, r)}</td>`)}</tr>`)}</tbody>
  </table></div>`;
}

function Elapsed() {
  const [s, setS] = useState(0);
  useEffect(() => { const t0 = Date.now(); const t = setInterval(() => setS(Math.floor((Date.now() - t0) / 1000)), 1000); return () => clearInterval(t); }, []);
  return html`<span>${s}s${s >= 20 ? " · a large customer or a long date range takes longer; it stops at about 55s" : ""}</span>`;
}

function Results({ res, running, changes, basic }) {
  const [tab, setTab] = useState("");
  if (running || (res && res.loading)) return html`<div className="card"><div className="muted pad">Searching bills… <${Elapsed} /></div></div>`;
  if (!res) return null;
  if (res.error) return html`<div className="card"><div className="err pad">${res.error}</div></div>`;
  const rows = res.rows || [];
  const targets = res.targets || [];
  const obs = res.obs || {};
  const view = tab === "bills" || targets.includes(tab) ? tab : (targets[0] || "bills");
  // preview columns for the observation shown: one per change on it
  const live = (changes || []).filter(c => c.target === view);
  const newCols = live.map(c => {
    if (c.action === "remove") return {
      k: "act_" + c.id, l: "Action", get: () => "Remove",
      render: () => html`<span className="gone">Remove</span>` };
    const f = CHANGE_FIELDS.find(x => x.id === c.field) || CHANGE_FIELDS[0];
    return {
      k: "new_" + c.id, l: "New " + (f.id === "uom" ? "UOM" : f.label.toLowerCase()),
      get: () => c.value || "",
      render: r => !c.value ? html`<span className="muted">Not selected</span>`
        : String(r[f.id] || "") === c.value ? html`<span className="muted">${c.value} (no change)</span>`
        : html`<span className="new">${c.value}</span>`
    };
  });
  const isObs = view !== "bills";
  const cols = isObs ? OBS_COLS.concat(newCols) : COLS;
  const list = isObs ? ((obs[view] || {}).rows || []) : rows;
  const total = isObs ? ((obs[view] || {}).total || 0) : res.total;
  const noun = isObs ? "line" : "bill";
  const tabName = t => basic && targets.length === 1 ? "Matching lines" : "Line " + t;
  return html`<div className="card">
    <div className="card-head">
      ${targets.length ? html`<div className="tabs">
        ${targets.map(t => html`<button key=${t} type="button" className=${"tab" + (view === t ? " on" : "")} onClick=${() => setTab(t)}>${tabName(t)} · ${((obs[t] || {}).total || 0).toLocaleString()}</button>`)}
        <button type="button" className=${"tab" + (view === "bills" ? " on" : "")} onClick=${() => setTab("bills")}>Bills · ${res.total.toLocaleString()}</button>
      </div>` : html`<h2>Matching bills</h2>`}
      <span className="pill">${total.toLocaleString()} ${noun}${total === 1 ? "" : "s"}${total > list.length ? " · showing newest " + list.length : ""}</span>
      <span className="muted small">${(res.ms / 1000).toFixed(1)}s</span>
      <span className="grow"></span>
      ${list.length > 0 && html`<button type="button" className="btn ghost" onClick=${() => appsmith.triggerEvent("onDownload", {
        csv: toCsv(cols, list), fileName: isObs ? "matching-lines" + (basic ? "" : "-" + view) + ".csv" : "matching-bills.csv" })}>Download CSV</button>`}
    </div>
    ${isObs && live.length > 0 && html`<div className="muted small">Preview only: nothing is changed in UBM.</div>`}
    ${!list.length ? html`<div className="muted pad">No ${noun}s match these conditions in this date range.</div>`
      : html`<${Table} cols=${cols} rows=${list} keyOf=${(r, i) => isObs ? r.bill_id + "-" + i : r.bill_id} />`}
  </div>`;
}

/* ---------- rule pages, laid out as in the mockups ---------- */

const num = v => v == null || v === "" ? "" : Number(v).toLocaleString(undefined, { maximumFractionDigits: 4 });
const partOf = (res, key, id) => res && res.key === key && res.parts ? res.parts[id] || null : null;
const linesOf = (part, name) => (part && part.lines && part.lines[name]) || { rows: [], total: 0, bills: 0 };
const typeOf = r => r.description || r.code || "";
const CMP2 = [{ value: "eq", label: "is equal to" }, { value: "neq", label: "is not equal to" },
  { value: "gt", label: "greater than" }, { value: "lt", label: "less than" }];
const EXISTS_OPTS = [{ value: "exists", label: "exists" }, { value: "not_exists", label: "does not exist" }];

/* field / operator / value for one line letter, without the row chrome */
function LineCond({ c, ctx, onChange, fieldIds }) {
  const fields = ctx.F.obs.filter(f => !f.hide && (!fieldIds || fieldIds.includes(f.id)));
  const name = String(c.field || "").split(".")[0] || "A";
  const f = ctx.fieldOf(c.field);
  const set = p => onChange(Object.assign({}, c, p));
  return html`<${React.Fragment}>
    <${Select} value=${String(c.field || "").split(".")[1] || ""} search=${true} placeholder="Choose field…"
      options=${fields.map(x => ({ value: x.id, label: x.label.replace(/ \(code\)$/, "") }))}
      onChange=${v => { const nf = ctx.fieldOf(name + "." + v); set({ field: name + "." + v, op: nf ? ctx.ops[nf.type][0] : "", value: "", mode: "value", valueField: "" }); }} />
    <${Select} value=${c.op} search=${false} disabled=${!f} placeholder="Operator"
      options=${(f ? ctx.ops[f.type] : []).map(o => ({ value: o, label: ctx.opLabels[o] }))}
      onChange=${op => set({ op, value: op === "in" || op === "not_in" ? [] : op === "between" ? ["", ""] : (Array.isArray(c.value) ? "" : c.value) })} />
    <${ValueEditor} c=${c} f=${f} options=${f && f.options ? (ctx.values[f.options] || []) : []} compareFields=${[]} onChange=${onChange} /><//>`;
}

function Foot({ status, warn, running, onRun, onClear, onSql, showSql, sqlInfo, canRun }) {
  const obs = (sqlInfo && sqlInfo.obs) || {};
  const label = k => { const [id, L] = k.split(" "); return (/^r\d$/.test(id) ? "Rule " + id.slice(1) + " · " : "") + "line " + L; };
  return html`<div className="foot-wrap">
    <div className="foot">
      <span className=${"dot" + (warn ? " warn" : "")}></span><span className="foot-txt">${sqlInfo && sqlInfo.error ? html`<span className="err">${sqlInfo.error}</span>` : status}</span>
      <span className="grow"></span>
      <button type="button" className="btn ghost" onClick=${onClear}>Clear all</button>
      <button type="button" className="btn ghost" onClick=${onSql}>${showSql ? "Hide SQL" : "Show SQL"}</button>
      <button type="button" className="btn primary" disabled=${running || !canRun} onClick=${onRun}>${running ? "Running…" : "Run query"}</button>
    </div>
    ${showSql && Object.keys(obs).length > 0 && html`<pre className="sql">${Object.keys(obs).map(k => "-- Matching " + label(k) + "\n" + obs[k]).join("\n\n")}</pre>`}
  </div>`;
}

function Dates({ rule, set }) {
  return html`<span className="dates">
    <label className="muted small">Bills dated</label>
    <input className="inp date" type="date" value=${rule.dateFrom} onInput=${e => set({ dateFrom: e.target.value })} />
    <span className="muted small">to</span>
    <input className="inp date" type="date" value=${rule.dateTo} onInput=${e => set({ dateTo: e.target.value })} />
  </span>`;
}

function Badge({ ok, yes, no }) {
  return html`<span className=${"badge-st " + (ok ? "ok" : "need")}>${ok ? yes : no}</span>`;
}

function ResultLine({ part, noun }) {
  if (!part) return null;
  if (part.error) return html`<div className="err small">${part.error}</div>`;
  return null;
}

/* the matched lines with the change, as Bill | Field | Current → New */
function ChangeTable({ part, changes, ctx, limit }) {
  const rows = [];
  (changes || []).forEach(c => {
    linesOf(part, c.target).rows.forEach(r => {
      if (c.action === "remove") rows.push({ bill: r.bill_id, field: "Observation", cur: typeOf(r), nw: "Removed", gone: true });
      else {
        const f = CHANGE_FIELDS.find(x => x.id === c.field) || CHANGE_FIELDS[0];
        rows.push({ bill: r.bill_id, field: f.label, cur: r[c.field] == null ? "" : String(r[c.field]), nw: c.value });
      }
    });
  });
  if (!rows.length) return html`<div className="muted pad">No matching lines in this date range.</div>`;
  return html`<div className="tbl-wrap"><table className="tbl ptbl">
    <thead><tr><th>Bill</th><th>Field</th><th>Current value</th><th></th><th>New value</th></tr></thead>
    <tbody>${rows.slice(0, limit || 500).map((r, i) => html`<tr key=${i}>
      <td><a className="link strong" onClick=${() => appsmith.triggerEvent("onOpenBill", { billId: r.bill })}>${r.bill}</a></td>
      <td>${r.field}</td><td><span className="chip">${r.cur || "—"}</span></td><td className="arrow">→</td>
      <td>${r.nw ? html`<span className=${r.gone ? "gone" : "new"}>${r.nw}</span>` : html`<span className="muted">Not selected</span>`}</td>
    </tr>`)}</tbody></table></div>`;
}

const csvOf = (head, rows) => {
  const q = v => { const s = v == null ? "" : String(v); return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
  return [head.join(",")].concat(rows.map(r => r.map(q).join(","))).join("\n");
};

/* ---- Demand units ---- */
function DemandView({ p, setP, ctx, rule, set, res, running, run, foot }) {
  const part = partOf(res, "demand", "demand");
  const A = linesOf(part, "A");
  const codeCond = p.conds.find(c => c.field === "A.code" && (c.op === "in" || c.op === "not_in"));
  const [q, setQ] = useState("");
  const pool = Array.from(new Set(DEMAND_CODES.concat((ctx.values.code || []).map(o => o.value).filter(c => /DEM/i.test(c))).concat(codeCond ? codeCond.value : [])));
  const shown = pool.filter(c => !q || c.toLowerCase().includes(q.toLowerCase()));
  const sel = codeCond ? codeCond.value : [];
  const setConds = conds => setP(Object.assign({}, p, { conds }));
  const setCode = v => setConds(p.conds.map(c => c === codeCond ? Object.assign({}, c, { value: v }) : c));
  const uoms = asOpts(ctx.values.uom || []);
  return html`<div className="view">
    <div className="card">
      <div className="card-head"><h2>Find matching observations</h2><span className="grow"></span><${Dates} rule=${rule} set=${set} /></div>
      ${p.conds.map((c, i) => html`<div key=${c.id} className="row">
        <span className="lead">${i ? "AND" : "Where"}</span>
        <${LineCond} c=${c} ctx=${ctx} onChange=${nc => setConds(p.conds.map(x => x.id === c.id ? nc : x))} />
        ${i > 1 ? html`<button type="button" className="x" title="Remove condition" onClick=${() => setConds(p.conds.filter(x => x.id !== c.id))}>×</button>` : html`<span></span>`}
      </div>`)}
      <div className="muted small">Both conditions must match the same observation.</div>
      ${codeCond && html`<div className="subcard">
        <div className="sub-h">Selected observation types (${sel.length})</div>
        <input className="inp" placeholder="Search observation types" value=${q} onInput=${e => setQ(e.target.value)} />
        <div className="checks">${shown.map(c => html`<label key=${c} className="chk">
          <input type="checkbox" checked=${sel.includes(c)} onChange=${() => setCode(sel.includes(c) ? sel.filter(x => x !== c) : sel.concat([c]))} />
          <span className="mono">${c}</span></label>`)}</div>
      </div>`}
      <div className="card-actions">
        <a className="add-link" onClick=${() => setConds(p.conds.concat([Object.assign(newCond("A.uom"), { op: "eq" })]))}>+ Add condition</a>
      </div>
    </div>

    <div className="card">
      <div className="card-head"><h2>Changes to make</h2></div>
      <div className="target-row"><b>Target</b><span className="pill-blue">Matched observations only</span></div>
      <div className="row chg-mock">
        <${Select} value="set" search=${false} options=${[{ value: "set", label: "Set field" }]} onChange=${() => {}} />
        <${Select} value="uom" search=${false} options=${[{ value: "uom", label: "Unit of measure" }]} onChange=${() => {}} />
        <span className="lead to">to</span>
        <${Select} value=${p.newUom} free=${true} mono=${true} placeholder="Choose target unit…" options=${uoms} onChange=${v => setP(Object.assign({}, p, { newUom: v }))} />
      </div>
      <div className="muted small">Choose kw or kva for this rule. Create separate rules if the targets differ.</div>
      <div className="muted small">Changes the unit label; numeric values remain unchanged.</div>
    </div>

    ${(part || running) && html`<div className="card">
      <div className="card-head"><h2>Matching observations</h2>
        ${part && !part.error && html`<span className="pill">${A.total.toLocaleString()} observation${A.total === 1 ? "" : "s"} · ${A.bills.toLocaleString()} bill${A.bills === 1 ? "" : "s"}${A.total > A.rows.length ? " · showing newest " + A.rows.length : ""}</span>`}
        <span className="grow"></span>
        ${A.rows.length > 0 && html`<button type="button" className="btn ghost sm" onClick=${() => appsmith.triggerEvent("onDownload", { fileName: "demand-units.csv",
          csv: csvOf(["Bill", "Observation type", "Current UOM", "New UOM"], A.rows.map(r => [r.bill_id, r.code, r.uom, p.newUom])) })}>Download CSV</button>`}
      </div>
      ${running ? html`<div className="muted pad">Searching bills… <${Elapsed} /></div>` : html`<div className="res-body">
      <${ResultLine} part=${part} />
      ${part && !part.error && (A.rows.length ? html`<div className="tbl-wrap"><table className="tbl ptbl">
        <thead><tr><th>Bill</th><th>Observation type</th><th>Current UOM</th><th>New UOM</th></tr></thead>
        <tbody>${A.rows.map((r, i) => html`<tr key=${i}>
          <td><a className="link" onClick=${() => appsmith.triggerEvent("onOpenBill", { billId: r.bill_id })}>${r.bill_id}</a></td>
          <td className="mono">${r.code}</td><td>${r.uom}</td>
          <td>${p.newUom ? html`<span className="new">${p.newUom}</span>` : html`<span className="muted">Not selected</span>`}</td></tr>`)}</tbody>
      </table></div>` : html`<div className="muted pad">No matching observations in this date range.</div>`)}</div>`}
    </div>`}

    <${Foot} ...${foot} status=${part && !part.error ? A.total.toLocaleString() + " observations found" + (p.newUom ? "" : " · select a target unit to preview the change") : !p.newUom ? "Select a target unit to preview changes." : "Ready to run."}
      warn=${!p.newUom} />
  </div>`;
}

/* ---- Missing consumption ---- */
function MissingView({ p, setP, ctx, rule, set, res, running, run, foot }) {
  const part = partOf(res, "missing", "missing");
  const A = linesOf(part, "A");
  const first = (p.group.conditions || []).find(c => c.field === "A.code" && c.op === "eq");
  const step = part ? 3 : p.changes.some(c => c.value) ? 2 : 1;
  const setCh = changes => setP(Object.assign({}, p, { changes }));
  const ready = p.changes.length && p.changes.every(c => c.value);
  return html`<div className="view">
    <div className="steps">${["Find bills", "Define changes", "Review"].map((t, i) => html`<div key=${t} className=${"step" + (i + 1 === step ? " on" : i + 1 < step ? " done" : "")}>
      <span className="step-n">${i + 1}</span><span>${t}</span></div>`)}</div>
    <div className="card">
      <div className="card-head"><h2>Find matching bills</h2><span className="grow"></span><${Dates} rule=${rule} set=${set} />
        <${Select} className="w-match" value=${p.group.match} search=${false} options=${MATCH_OPTS} onChange=${v => setP(Object.assign({}, p, { group: Object.assign({}, p.group, { match: v }) }))} /></div>
      <div className="row">
        <span className="lead">Where</span>
        <${Select} value="consumption" search=${false} options=${[{ value: "consumption", label: "Consumption line item" }]} onChange=${() => {}} />
        <${Select} value=${p.consumption} search=${false} options=${EXISTS_OPTS} onChange=${v => setP(Object.assign({}, p, { consumption: v }))} />
        <div className="val-empty"></div><span></span>
      </div>
      <${Group} node=${p.group} depth=${0} fieldList=${ctx.lineFields} ctx=${ctx} defaultField="A.code" firstLead="AND"
        onChange=${n => setP(Object.assign({}, p, { group: n }))} />
      <div className="muted small">Both conditions must match the same bill.</div>
    </div>

    <div className="card">
      <div className="card-head"><h2>Changes to make</h2><span className="grow"></span>
        <span className="pill-green">Target: matched ${first && first.value ? first.value : "BILLEDUSE_USE"} observations</span></div>
      ${p.changes.map(c => html`<div key=${c.id} className="row chg-mock">
        <${Select} value="set" search=${false} options=${[{ value: "set", label: "Set field" }]} onChange=${() => {}} />
        <${Select} value=${c.field} search=${false} options=${CHANGE_FIELDS.map(f => ({ value: f.id, label: f.label }))}
          onChange=${v => setCh(p.changes.map(x => x.id === c.id ? Object.assign({}, x, { field: v, value: "" }) : x))} />
        <span className="lead to">to</span>
        <${Select} value=${c.value} free=${true} mono=${true} placeholder="Choose the new value…" options=${asOpts(ctx.values[c.field] || [])}
          onChange=${v => setCh(p.changes.map(x => x.id === c.id ? Object.assign({}, x, { value: v }) : x))} />
        ${p.changes.length > 1 ? html`<button type="button" className="x" title="Remove change" onClick=${() => setCh(p.changes.filter(x => x.id !== c.id))}>×</button>` : html`<span></span>`}
      </div>`)}
      <div><button type="button" className="btn ghost sm" onClick=${() => setCh(p.changes.concat([newChange("A", { field: "code" })]))}>+ Add field change</button></div>
      <div className="muted small">Only matching observations are updated.</div>
    </div>

    ${(part || running) && html`<div className="card">
      <div className="card-head"><h2>Preview changes</h2>
        ${part && !part.error && html`<span className="muted small">${A.bills.toLocaleString()} bills · ${A.total.toLocaleString()} observations${A.total > A.rows.length ? " · showing newest " + A.rows.length : ""}</span>`}</div>
      ${running ? html`<div className="muted pad">Searching bills… <${Elapsed} /></div>` : html`<div className="res-body"><${ResultLine} part=${part} />${part && !part.error && html`<${ChangeTable} part=${part} changes=${p.changes} ctx=${ctx} />`}</div>`}
    </div>`}

    <${Foot} ...${foot} status=${part && !part.error ? A.total.toLocaleString() + " observations found" : ready ? "Ready to run." : "Choose the new value to preview changes."}
      warn=${!ready} />
  </div>`;
}

/* ---- pair rows (A / B) used by Duplicate generation, Constellation, Peak usage, Duplicate demand ---- */
function PairRow({ letter, c, mode, ctx, onChange, onMode, onRemove }) {
  return html`<div className="row pair">
    <span className="lead letter">${letter}</span>
    <${LineCond} c=${c} ctx=${ctx} onChange=${onChange} />
    <${Select} value=${mode} search=${false} options=${EXISTS_OPTS} onChange=${onMode} />
    ${onRemove ? html`<button type="button" className="x" title="Remove condition" onClick=${onRemove}>×</button>` : html`<span></span>`}
  </div>`;
}

function PairFinder({ p, setP, ctx, rule, set, title, note, match }) {
  const setRow = (k, v) => setP(Object.assign({}, p, { [k]: v }));
  return html`<div className="card">
    <div className="card-head"><h2>${title}</h2><span className="grow"></span><${Dates} rule=${rule} set=${set} />
      ${match && html`<${Select} className="w-match" value=${p.match || "ALL"} search=${false} options=${MATCH_OPTS.slice(0, 1)} onChange=${() => {}} />`}</div>
    <${PairRow} letter="A" c=${p.A} mode=${p.modeA} ctx=${ctx} onChange=${c => setRow("A", c)} onMode=${v => setRow("modeA", v)} />
    <${PairRow} letter="B" c=${p.B} mode=${p.modeB} ctx=${ctx} onChange=${c => setRow("B", c)} onMode=${v => setRow("modeB", v)} />
    ${(p.extra || []).map(x => html`<div key=${x.id} className="row pair">
      <${Select} className="letter-sel" value=${x.letter} search=${false} options=${[{ value: "A", label: "A" }, { value: "B", label: "B" }]}
        onChange=${v => setP(Object.assign({}, p, { extra: p.extra.map(y => y.id === x.id ? Object.assign({}, y, { letter: v, c: Object.assign({}, y.c, { field: v + "." + String(y.c.field).split(".")[1] }) }) : y) }))} />
      <${LineCond} c=${x.c} ctx=${ctx} onChange=${c => setP(Object.assign({}, p, { extra: p.extra.map(y => y.id === x.id ? Object.assign({}, y, { c }) : y) }))} />
      <span className="muted small">and</span>
      <button type="button" className="x" title="Remove condition" onClick=${() => setP(Object.assign({}, p, { extra: p.extra.filter(y => y.id !== x.id) }))}>×</button>
    </div>`)}
    <div className="muted small">${note}</div>
    <div><button type="button" className="btn primary sm" onClick=${() => setP(Object.assign({}, p, { extra: (p.extra || []).concat([{ id: uid(), letter: "A", c: Object.assign(newCond("A.uom"), { op: "eq" }) }]) }))}>+ Add condition</button></div>
  </div>`;
}

/* the pair as compiler aliases */
const pairAliases = p => ["A", "B"].map(L => ({ name: L, mode: p["mode" + L], match: "ALL",
  conditions: [p[L]].concat((p.extra || []).filter(x => x.letter === L).map(x => x.c)) }));

/* first bill where A and B both matched and the comparison holds */
function pairExample(part, left, op, right) {
  const A = linesOf(part, "A").rows, B = linesOf(part, "B").rows;
  const val = (r, ref) => r[String(ref).split(".")[1]];
  const ok = (x, y) => { const a = Number(x), b = Number(y); return op === "eq" ? a === b : op === "neq" ? a !== b : op === "gt" ? a > b : op === "lt" ? a < b : true; };
  for (const a of A) {
    const b = B.find(r => r.bill_id === a.bill_id && ok(val(a, left), val(r, right)));
    if (b) return { bill: a.bill_id, a, b };
  }
  return null;
}

function Example({ ex, after }) {
  if (!ex) return null;
  const line = (r, cls, label, minus) => html`<div className=${"ex-line " + (cls || "")}>${minus && html`<span className="minus">−</span>`}<span className=${cls === "struck" ? "strike" : ""}>${label || typeOf(r)}</span><span className="ex-v">${num(r.usage)}</span></div>`;
  return html`<div className="example">
    <div className="ex-h">Example bill <a className="link" onClick=${() => appsmith.triggerEvent("onOpenBill", { billId: ex.bill })}>${ex.bill}</a></div>
    <div className="ex-body">
      <div><div className="ex-k">Before</div>${after.removeA ? line(ex.a, "struck", null, true) : line(ex.a)}${after.removeB ? line(ex.b, "struck", null, true) : line(ex.b)}</div>
      <div className="ex-arrow">→</div>
      <div><div className="ex-k">After</div>
        ${!after.removeA && line(ex.a, after.newA ? "after" : "", after.newA)}
        ${!after.removeB && line(ex.b, after.newB || after.removeA ? "after" : "", after.newB)}</div>
    </div>
  </div>`;
}

function PairRuleCard({ n, title, p, setP, ctx, part, provider }) {
  const r = p;
  const letterLabel = L => L + " · " + (r.pair[L].value || "?");
  const valueOpts = ["A", "B"].flatMap(L => [{ value: L + ".usage", label: L + ".Value" }, { value: L + ".charge", label: L + ".Charge" }]);
  const ex = part && !part.error ? pairExample(part, r.left, r.op, r.right) : null;
  const keep = r.target === "A" ? "B" : "A";
  const A = linesOf(part, r.target);
  return html`<div className="card rule">
    <h2>Rule ${n} · ${title}</h2>
    ${provider && html`<div className="iff"><span className="lead">IF</span>
      <${Select} value="vendor" search=${false} options=${[{ value: "vendor", label: "Provider" }]} onChange=${() => {}} />
      <${Select} value=${r.provOp} search=${false} options=${[{ value: "contains", label: "contains" }, { value: "eq", label: "is equal to" }]} onChange=${v => setP({ provOp: v })} />
      <${Select} value=${r.provider} free=${true} options=${asOpts(ctx.values.vendor || [])} onChange=${v => setP({ provider: v })} /></div>`}
    <div className="iff"><span className="lead">${provider ? "AND" : "IF"}</span>
      <${Select} value=${r.left} search=${false} options=${valueOpts.filter(o => o.value.startsWith("A"))} onChange=${v => setP({ left: v })} />
      <${Select} value=${r.op} search=${false} options=${CMP2} onChange=${v => setP({ op: v })} />
      <${Select} value=${r.right} search=${false} options=${valueOpts.filter(o => o.value.startsWith("B"))} onChange=${v => setP({ right: v })} /></div>
    <div className="iff then"><span className="lead">THEN</span>
      ${r.action === "remove"
        ? html`<${React.Fragment}><${Select} className="danger-sel" value="remove" search=${false} options=${[{ value: "remove", label: "Remove observation" }, { value: "set", label: "Set " + r.target + ".Type to" }]} onChange=${v => setP({ action: v })} />
           <${Select} className="danger-sel" value=${r.target} search=${false} options=${["A", "B"].map(L => ({ value: L, label: letterLabel(L) }))} onChange=${v => setP({ target: v })} /><//>`
        : html`<${React.Fragment}><${Select} value="set" search=${false} options=${[{ value: "set", label: "Set " + r.target + ".Type to" }, { value: "remove", label: "Remove observation" }]} onChange=${v => setP({ action: v })} />
           <${Select} value=${r.value} free=${true} options=${asOpts(ctx.values.description || [])} placeholder="Choose new type…" onChange=${v => setP({ value: v })} /><//>`}
    </div>
    <div className="muted small">Keep ${letterLabel(keep)}.</div>
    ${part && part.error && html`<div className="err small">${part.error}</div>`}
    ${part && !part.error && html`<div className="muted small">${A.total.toLocaleString()} matching pair${A.total === 1 ? "" : "s"} on ${A.bills.toLocaleString()} bill${A.bills === 1 ? "" : "s"}.</div>`}
    ${part && !part.error && !ex && html`<div className="muted small">No example bill in the newest results.</div>`}
    <${Example} ex=${ex} after=${{ removeA: r.action === "remove" && r.target === "A", removeB: r.action === "remove" && r.target === "B",
      newA: r.action === "set" && r.target === "A" ? r.value : "", newB: r.action === "set" && r.target === "B" ? r.value : "" }} />
  </div>`;
}

const pairSpec = (p, r, provider) => ({
  conditions: [],
  aliases: pairAliases(p).map(a => provider && a.name === "A" && r.provider
    ? Object.assign({}, a, { conditions: a.conditions.concat([Object.assign(newCond("A.vendor"), { op: r.provOp, value: r.provider })]) }) : a),
  cross: [Object.assign(newCond(r.left), { op: r.op, mode: "field", valueField: r.right })],
  changes: [r.action === "remove" ? newChange(r.target, { action: "remove" }) : newChange(r.target, { field: "description", value: r.value })],
  listAll: true
});

function GenerationView({ p, setP, ctx, rule, set, res, running, run, which, foot }) {
  const key = which;
  const sub = k => v => setP(Object.assign({}, p, { [k]: Object.assign({}, p[k], v) }));
  const r1 = Object.assign({}, p.r1, { pair: p }), r2 = Object.assign({}, p.r2, { pair: p });
  const showR1 = which === "dupgen", ready = r2.action === "remove" || !!r2.value;
  return html`<div className="view">
    <${PairFinder} p=${p} setP=${setP} ctx=${ctx} rule=${rule} set=${set} title="Find a matching pair" note="A and B must belong to the same bill." />
    <div className=${showR1 ? "rules2" : ""}>
      ${showR1 && html`<${PairRuleCard} n=${1} title="Equal values" p=${r1} setP=${sub("r1")} ctx=${ctx} part=${partOf(res, key, "r1")} />`}
      <${PairRuleCard} n=${showR1 ? 2 : 1} title="Constellation" p=${r2} setP=${sub("r2")} ctx=${ctx} part=${partOf(res, key, "r2")} provider=${true} />
    </div>
    ${running && html`<div className="card"><div className="muted pad">Searching bills… <${Elapsed} /></div></div>`}
    <div className="info"><span className="info-i">i</span> Multiple possible pairs are flagged for review.</div>
    <${Foot} ...${foot} status=${ready ? "Ready to run." : "Choose the new type for the Constellation rule."} warn=${!ready} />
  </div>`;
}

function PeakView({ p, setP, ctx, rule, set, res, running, run, which, foot }) {
  const key = which;
  const r1 = p.r1, r2 = p.r2;
  const setR = k => v => setP(Object.assign({}, p, { [k]: Object.assign({}, p[k], v) }));
  const ready1 = r1.changes.length > 0 && r1.changes.every(c => c.value && c.target);
  const ready2 = !!r2.remove;
  const part1 = partOf(res, key, "r1"), part2 = partOf(res, key, "r2");
  const ex1 = part1 && !part1.error ? pairExample(part1, "A.usage", "any", "B.usage") : null;
  const showR1 = which === "peak";
  const label = (pp, L) => L + " · " + (pp[L].value || "?");
  const descs = asOpts(ctx.values.description || []);
  return html`<div className="view">
    ${showR1 && html`<div className="card">
      <div className="card-head"><h2>Rule 1 · Correct peak usage</h2><${Badge} ok=${ready1} yes="Ready to preview" no="Needs a new value" /><span className="grow"></span><${Dates} rule=${rule} set=${set} /></div>
      <div className="sub-h">Find matching bills</div>
      <div><${Select} className="w-match" value="ALL" search=${false} options=${MATCH_OPTS.slice(0, 1)} onChange=${() => {}} /></div>
      <${PairRow} letter="A" c=${r1.A} mode=${r1.modeA} ctx=${ctx} onChange=${c => setR("r1")({ A: c })} onMode=${v => setR("r1")({ modeA: v })} />
      <${PairRow} letter="B" c=${r1.B} mode=${r1.modeB} ctx=${ctx} onChange=${c => setR("r1")({ B: c })} onMode=${v => setR("r1")({ modeB: v })} />
      <div className="muted small">A and B must exist on the same bill.</div>
      <div className="sub-h">Changes</div>
      <div className="tbl-wrap"><table className="tbl ctbl">
        <thead><tr><th>Target</th><th>Field</th><th>New value</th><th></th></tr></thead>
        <tbody>${r1.changes.map(c => html`<tr key=${c.id}>
          <td><${Select} value=${c.target} search=${false} options=${["A", "B"].map(L => ({ value: L, label: label(r1, L) }))}
            onChange=${v => setR("r1")({ changes: r1.changes.map(x => x.id === c.id ? Object.assign({}, x, { target: v }) : x) })} /></td>
          <td><${Select} value=${c.field} search=${false} options=${CHANGE_FIELDS.map(f => ({ value: f.id, label: f.id === "description" ? "Observation type" : f.label }))}
            onChange=${v => setR("r1")({ changes: r1.changes.map(x => x.id === c.id ? Object.assign({}, x, { field: v, value: "" }) : x) })} /></td>
          <td><${Select} className=${c.value ? "good-sel" : ""} value=${c.value} free=${true} options=${asOpts(ctx.values[c.field] || [])} placeholder="Choose new value…"
            onChange=${v => setR("r1")({ changes: r1.changes.map(x => x.id === c.id ? Object.assign({}, x, { value: v }) : x) })} /></td>
          <td>${r1.changes.length > 1 && html`<button type="button" className="x" title="Remove change" onClick=${() => setR("r1")({ changes: r1.changes.filter(x => x.id !== c.id) })}>×</button>`}</td>
        </tr>`)}</tbody></table></div>
      <div><a className="add-link" onClick=${() => setR("r1")({ changes: r1.changes.concat([newChange("A", { field: "description" })]) })}>+ Add field change</a></div>
      ${part1 && part1.error && html`<div className="err small">${part1.error}</div>`}
      ${part1 && !part1.error && html`<div className="muted small">${linesOf(part1, "A").bills.toLocaleString()} bills have both lines.</div>`}
      ${ex1 && html`<div className="tbl-wrap"><table className="tbl ptbl">
        <thead><tr><th>Example bill</th><th>Current type</th><th>New type</th></tr></thead>
        <tbody>${["A", "B"].map(L => { const row = L === "A" ? ex1.a : ex1.b; const ch = r1.changes.find(c => c.target === L && c.field === "description");
          return html`<tr key=${L}><td><a className="link" onClick=${() => appsmith.triggerEvent("onOpenBill", { billId: ex1.bill })}>${ex1.bill}</a></td>
            <td>${typeOf(row)}</td><td>${ch && ch.value ? html`<span className="new">${ch.value}</span>` : html`<span className="muted">No change</span>`}</td></tr>`; })}</tbody>
      </table></div>`}
    </div>`}

    <div className="card">
      <div className="card-head"><h2>Rule ${showR1 ? 2 : 1} · Remove duplicate demand</h2><${Badge} ok=${ready2} yes="Ready to preview" no="Needs selection" />
        <span className="grow"></span>${!showR1 && html`<${Dates} rule=${rule} set=${set} />`}</div>
      <div className="dd">
        <div>
          ${["A", "B"].map((L, i) => html`<div key=${L} className="row dd-row">
            <span className="lead">${i ? "AND" : "Where"}</span>
            <${Select} value=${r2[L].value} free=${true} search=${true} options=${descs}
              onChange=${v => setR("r2")({ [L]: Object.assign({}, r2[L], { value: v }) })} />
            <${Select} value=${r2["mode" + L]} search=${false} options=${EXISTS_OPTS} onChange=${v => setR("r2")({ ["mode" + L]: v })} />
          </div>`)}
          <div className="row dd-row"><b>Remove observation</b>
            <${Select} value=${r2.remove} search=${false} placeholder="Choose one…" options=${["A", "B"].map(L => ({ value: L, label: r2[L].value }))} onChange=${v => setR("r2")({ remove: v })} /></div>
        </div>
        <div className="dd-pick">
          ${["A", "B"].map(L => html`<label key=${L} className="radio"><input type="radio" name="dd" checked=${r2.remove === L} onChange=${() => setR("r2")({ remove: L })} /> ${r2[L].value}</label>`)}
          <div className="muted small">Choose which observation to remove. The other will be retained.</div>
        </div>
      </div>
      ${part2 && part2.error && html`<div className="err small">${part2.error}</div>`}
      ${part2 && !part2.error && html`<div className="muted small">${r2.remove ? linesOf(part2, r2.remove).total.toLocaleString() + " lines to remove on " + linesOf(part2, r2.remove).bills.toLocaleString() + " bills."
        : linesOf(part2, "A").bills.toLocaleString() + " bills have both observations. Choose which one to remove to preview the change."}</div>`}
      ${part2 && !part2.error && r2.remove && html`<${ChangeTable} part=${part2} changes=${[newChange(r2.remove, { action: "remove" })]} ctx=${ctx} limit=${50} />`}
    </div>

    ${running && html`<div className="card"><div className="muted pad">Searching bills… <${Elapsed} /></div></div>`}
    <${Foot} ...${foot} status=${showR1 ? (ready1 && ready2 ? "Both rules are ready to preview." : ready1 ? "Only Rule 1 is ready to preview." : ready2 ? "Only Rule 2 is ready to preview." : "Choose the new values to preview changes.")
        : ready2 ? "Ready to run." : "Choose which observation to remove to preview the change."}
      warn=${showR1 ? !(ready1 && ready2) : !ready2} />
  </div>`;
}

/* default settings of each rule page */
const descCond = (L, value) => Object.assign(newCond(L + ".description"), { op: "eq", value });
const VIEW_DEFAULTS = {
  demand: values => {
    const codes = (values.code || []).map(o => o.value);
    const uoms = (values.uom || []).map(o => o.value);
    return { conds: [cond("A.code", "in", DEMAND_CODES.concat(codes.filter(c => /DEM/i.test(c) && !DEMAND_CODES.includes(c)))),
      cond("A.uom", "eq", uoms.find(u => /^kwh$/i.test(u)) || "KWH")], newUom: "" };
  },
  missing: () => ({ consumption: "not_exists", group: { match: "ALL", conditions: [cond("A.code", "eq", "BILLEDUSE_USE")] },
    changes: [newChange("A", { field: "code", value: "USE_USE" })] }),
  pair: () => ({ A: descCond("A", "Generation (U)"), B: descCond("B", "Generation (UC)"), modeA: "exists", modeB: "exists", extra: [],
    r1: { left: "A.usage", op: "eq", right: "B.usage", action: "remove", target: "A", value: "" },
    r2: { provOp: "contains", provider: "Constellation", left: "A.usage", op: "neq", right: "B.usage", action: "set", target: "B", value: "Adjustment (UC)" } }),
  peak: () => ({
    r1: { A: descCond("A", "Use - On Peak (U)"), B: descCond("B", "Use - Off Peak (U)"), modeA: "exists", modeB: "exists",
      changes: [newChange("A", { field: "description", value: "Billed On Peak (U)" }), newChange("B", { field: "description", value: "Billed Off Peak (U)" })] },
    r2: { A: descCond("A", "Demand - Billed (U)"), B: descCond("B", "Demand - Info (UC)"), modeA: "exists", modeB: "exists", remove: "" } })
};
const VIEW_OF = { demand: "demand", missing: "missing", dupgen: "pair", constellation: "pair", peak: "peak", dupdem: "peak" };

/* the compiler rules a page runs */
function viewSpecs(key, p) {
  if (key === "demand") return [{ id: "demand", rule: { aliases: [{ name: "A", mode: "exists", match: "ALL", conditions: p.conds }],
    changes: [newChange("A", { field: "uom", value: p.newUom })], listAll: true } }];
  if (key === "missing") return [{ id: "missing", rule: { aliases: [
    { name: "A", mode: "exists", match: p.group.match, conditions: p.group.conditions },
    { name: "B", mode: p.consumption, match: "ALL", conditions: [cond("B.code", "eq", "USE_USE")] }],
    changes: p.changes } }];
  if (key === "dupgen" || key === "constellation") {
    const out = [{ id: "r2", rule: pairSpec(p, p.r2, true) }];
    return key === "dupgen" ? [{ id: "r1", rule: pairSpec(p, p.r1, false) }].concat(out) : out;
  }
  if (key === "peak" || key === "dupdem") {
    const r1 = p.r1, r2 = p.r2, out = [];
    if (key === "peak") out.push({ id: "r1", rule: { aliases: [
      { name: "A", mode: r1.modeA, match: "ALL", conditions: [r1.A] }, { name: "B", mode: r1.modeB, match: "ALL", conditions: [r1.B] }],
      changes: r1.changes, listAll: true } });
    out.push({ id: "r2", rule: { aliases: [
      { name: "A", mode: r2.modeA, match: "ALL", conditions: [r2.A] }, { name: "B", mode: r2.modeB, match: "ALL", conditions: [r2.B] }],
      changes: r2.remove ? [newChange(r2.remove, { action: "remove" })] : [], listAll: !r2.remove } });
    return out;
  }
  return [];
}

/* ---------- app ---------- */

function App() {
  const m = useModel();
  // native controls (date picker icon, scrollbars) follow the theme: dark or light
  useEffect(() => {
    const c = (m.theme && m.theme.colors) || (appsmith.theme && (appsmith.theme.colors || appsmith.theme)) || {};
    let bg = String(c.backgroundColor || c.surfaceColor || "");
    if (!bg) bg = window.getComputedStyle(document.documentElement).getPropertyValue("--appsmith-theme-backgroundColor").trim();
    const hex = bg.replace("#", "");
    const full = hex.length === 3 ? hex.split("").map(x => x + x).join("") : hex;
    if (!/^[0-9a-f]{6}$/i.test(full)) return;
    const [r, g, b] = [0, 2, 4].map(i => parseInt(full.slice(i, i + 2), 16));
    document.documentElement.setAttribute("data-scheme", (0.299 * r + 0.587 * g + 0.114 * b) < 140 ? "dark" : "light");
  });
  const F = m.fields || { bill: [], obs: [], ops: {}, opLabels: {} };
  const [rule, setRule] = useState(blankRule);
  const [showSql, setShowSql] = useState(false);
  const [advanced, setAdvanced] = useState(false);
  const [params, setParams] = useState({});
  const [hidden, setHidden] = useState("");
  const defaultsRef = useRef({});
  const loaded = useRef(false);

  useEffect(() => {
    if (loaded.current || !m.fields) return;
    loaded.current = true;
    if (m.savedRule) { const r = withIds(m.savedRule); setRule(VIEW_OF[r.key] ? Object.assign(blankRule(), { key: r.key, dateFrom: r.dateFrom, dateTo: r.dateTo }) : r); setAdvanced(needsAdvanced(r)); }
  }, [m.fields, m.savedRule]);

  const values = useMemo(() => {
    const out = {};
    (m.values || []).forEach(r => {
      if (r.value == null || r.value === "") return;
      (out[r.field] = out[r.field] || []).push({ value: String(r.value), n: Number(r.n) || 0 });
    });
    Object.keys(out).forEach(k => out[k].sort((a, b) => b.n - a.n));
    return out;
  }, [m.values]);

  const billFields = F.bill.map(f => ({ ref: "bill." + f.id, label: f.label, f }));
  const aliasFields = name => F.obs.filter(f => !f.hide).map(f => ({ ref: name + "." + f.id, label: name + " · " + f.label, f }));
  const ctx = {
    F, ops: F.ops, opLabels: F.opLabels, values,
    lineFields: F.obs.filter(f => !f.hide).map(f => ({ ref: "A." + f.id, label: f.label, f })),
    fieldOf: ref => {
      const s = String(ref || ""), i = s.indexOf(".");
      if (i < 0) return null;
      return (s.slice(0, i) === "bill" ? F.bill : F.obs).find(f => f.id === s.slice(i + 1)) || null;
    }
  };
  const set = p => setRule(Object.assign({}, rule, p));
  const present = rule.aliases.filter(a => a.mode !== "not_exists");
  const crossFields = [].concat(...present.map(a => aliasFields(a.name)));
  const keepFor = name => c => [c.field, c.mode === "field" ? c.valueField : ""].every(r => !r || !r.startsWith(name + "."));

  const addAlias = () => {
    const name = LETTERS.find(l => !rule.aliases.some(a => a.name === l));
    if (!name) return;
    const c = Object.assign(newCond(name + ".code"), { op: "eq" });
    set({ aliases: rule.aliases.concat([{ id: uid(), name, mode: "exists", match: "ALL", conditions: [c] }]) });
  };
  const send = ev => {
    if (ev === "onPreview") setShowSql(true);
    appsmith.triggerEvent(ev, { rule: JSON.parse(JSON.stringify(rule)) });
  };
  const sqlInfo = m.sqlInfo || {};
  const res = m.result;
  const err = sqlInfo.error || (res && res.error) || "";
  const running = !!m.running || !!(res && res.loading);
  const countConds = n => {
    let t = 0;
    const stack = [n];
    while (stack.length) (stack.pop().conditions || []).forEach(k => { if (k.conditions) stack.push(k); else if (k.field) t++; });
    return t;
  };
  const count = countConds(rule) + rule.aliases.reduce((t, a) => t + countConds(a), 0) + rule.cross.filter(c => c.field).length;
  const info = ruleInfo(rule.key);
  const pickRule = r => {
    const base = blankRule();
    setRule(Object.assign(base, { key: r.key, dateFrom: rule.dateFrom, dateTo: rule.dateTo }));
    setAdvanced(needsAdvanced(base));
    setShowSql(false);
  };
  // the mockup pages keep their own settings, one set per page
  const vkey = VIEW_OF[rule.key];
  // Defaults are built once per page and kept: rebuilding them on every redraw
  // (the model refreshes twice a second) gave rows new ids, which remounted
  // them and closed any open dropdown. They are rebuilt once when the value
  // lists first arrive, since Demand units reads the customer's codes.
  const hasValues = Object.keys(values).length > 0;
  const cached = vkey ? defaultsRef.current[vkey] : null;
  if (vkey && !params[vkey] && (!cached || (!cached.hasValues && hasValues))) {
    defaultsRef.current[vkey] = { hasValues, p: VIEW_DEFAULTS[vkey](values) };
  }
  const vp = vkey ? (params[vkey] || defaultsRef.current[vkey].p) : null;
  const setVp = v => setParams(Object.assign({}, params, { [vkey]: v }));
  const runView = () => appsmith.triggerEvent("onRunSet", { set: viewSet() });
  const viewSet = () => ({ key: rule.key,
    rules: viewSpecs(rule.key, vp).map(x => ({ id: x.id, rule: JSON.parse(JSON.stringify(Object.assign({ match: "ALL", conditions: [], cross: [], changes: [] }, x.rule, { key: rule.key, dateFrom: rule.dateFrom, dateTo: rule.dateTo }))) })) });
  const viewRunning = !!m.running || !!(m.result && m.result.loading && m.result.key === rule.key);
  const viewRes = hidden === rule.key ? null : m.result;
  const foot = { running: viewRunning, canRun: !!m.cust, showSql, sqlInfo: m.sqlInfo,
    onRun: () => { setHidden(""); runView(); },
    onSql: () => { if (showSql) setShowSql(false); else { setShowSql(true); appsmith.triggerEvent("onPreviewSet", { set: viewSet() }); } },
    onClear: () => { delete defaultsRef.current[vkey]; setParams(Object.assign({}, params, { [vkey]: undefined })); setHidden(rule.key); setShowSql(false); } };
  const viewProps = { p: vp, setP: setVp, ctx, rule, set, res: viewRes, running: viewRunning, run: runView, which: rule.key, foot };
  const forced = needsAdvanced(rule);
  const adv = advanced || forced;
  // Basic: bill conditions and line A's conditions shown as one list
  const lineA = rule.aliases.find(a => a.name === "A");
  const lineConds = lineA ? lineA.conditions || [] : [];
  const lineFields = F.obs.filter(f => !f.hide).map(f => ({ ref: "A." + f.id, label: "Line · " + f.label, f }));
  const basicFields = billFields.concat(lineFields);
  const putBasic = (billConds, lineList, changes) => {
    const ch = changes || rule.changes;
    const aliases = lineList.length || ch.length
      ? [Object.assign({ id: uid(), name: "A", mode: "exists", match: "ALL" }, lineA || {}, { conditions: lineList })] : [];
    set({ conditions: billConds, aliases, changes: ch });
  };
  const basicRow = (id, nc) => {
    const toLine = String(nc.field || "").startsWith("A.");
    const inBill = rule.conditions.some(x => x.id === id);
    let b = rule.conditions, l = lineConds;
    if (toLine) {
      b = b.filter(x => x.id !== id);
      l = inBill || !l.some(x => x.id === id) ? l.concat([nc]) : l.map(x => x.id === id ? nc : x);
    } else {
      l = l.filter(x => x.id !== id);
      b = inBill ? b.map(x => x.id === id ? nc : x) : b.concat([nc]);
    }
    putBasic(b, l);
  };
  // rows keep the order they were added in, even when one moves between bill and line
  const idNum = c => Number(String(c.id).slice(1)) || 0;
  const basicRows = rule.conditions.concat(lineConds).sort((a, b) => idNum(a) - idNum(b));
  // results belong to the rule that produced them
  const shownRes = res && res.key !== undefined && res.key !== rule.key ? null : res;

  return html`<div className="shell">
  <div className="title-row shell-title">
    <div><h1>${info.title}</h1><div className="muted">${info.sub}</div></div>
    <span className="grow"></span>
    ${!vkey && html`<label className=${"adv" + (forced ? " locked" : "")} title=${forced ? "This rule uses several lines, groups or comparisons, so it needs Advanced" : "Show groups, several lines and comparisons"}>
      <input type="checkbox" checked=${adv} disabled=${forced} onChange=${e => setAdvanced(e.target.checked)} />
      <span>Advanced</span>
    </label>`}
  </div>
  <nav className="nav">
    <div className="nav-h">Correction rules</div>
    ${RULES.map(r => html`<a key=${r.key} className=${"nav-i" + (rule.key === r.key ? " on" : "")} onClick=${() => pickRule(r)}>${r.nav}</a>`)}
    <div className="nav-sep"></div>
    <a className=${"nav-i" + (rule.key === "custom" ? " on" : "")} onClick=${() => pickRule(CUSTOM)}>${CUSTOM.nav}</a>
  </nav>
  <div className="page">
    ${vkey === "demand" && html`<${DemandView} ...${viewProps} />`}
    ${vkey === "missing" && html`<${MissingView} ...${viewProps} />`}
    ${vkey === "pair" && html`<${GenerationView} ...${viewProps} />`}
    ${vkey === "peak" && html`<${PeakView} ...${viewProps} />`}
    ${!vkey && !adv && html`<div key="basic-conditions" className="card">
      <div className="card-head">
        <h2>Conditions</h2>
        <span className="grow"></span>
        <label className="muted small">Bills dated</label>
        <input className="inp date" type="date" value=${rule.dateFrom} onInput=${e => set({ dateFrom: e.target.value })} />
        <span className="muted small">to</span>
        <input className="inp date" type="date" value=${rule.dateTo} onInput=${e => set({ dateTo: e.target.value })} />
      </div>
      <div className="muted small hint">${basicRows.length ? "All conditions must match. Line conditions must all match the same line on the bill." : "No conditions: every bill in the date range is found."}</div>
      ${basicRows.map((c, i) => html`<${CondRow} key=${c.id} c=${c} lead=${i ? "AND" : "Where"} fieldList=${basicFields} ctx=${ctx}
        onChange=${nc => basicRow(c.id, nc)}
        onRemove=${() => putBasic(rule.conditions.filter(x => x.id !== c.id), lineConds.filter(x => x.id !== c.id),
          lineConds.some(x => x.id === c.id) && lineConds.length === 1 ? [] : undefined)} />`)}
      <div className="adds"><button type="button" className="btn ghost sm" onClick=${() => set({ conditions: rule.conditions.concat([newCond()]) })}>+ Add condition</button></div>
    </div>

    <div key="basic-then" className="card">
      <div className="card-head"><h2>Then</h2>
        <span className="pill">Preview only</span>
        <span className="muted small">Shown next to each matching line. Nothing is saved to UBM.</span></div>
      ${!lineConds.length ? html`<div className="muted small">Add a line condition above (for example Line · Unit of measure) to choose which lines to change.</div>`
        : html`<div className="chg-list">${rule.changes.map(c => {
        const setC = p => set({ changes: rule.changes.map(x => x.id === c.id ? Object.assign({}, x, p) : x) });
        const remove = c.action === "remove";
        return html`<div key=${c.id} className="row chg-basic">
          <${Select} value=${c.action || "set"} search=${false} options=${BASIC_ACTIONS} onChange=${v => setC({ action: v, target: "A" })} />
          ${remove ? html`<div className="val chg-note muted small">Each matching line is removed from its bill.</div>`
            : html`<${Select} value=${c.field} search=${false} options=${CHANGE_FIELDS.map(f => ({ value: f.id, label: f.label }))}
            onChange=${v => setC({ field: v, value: "", target: "A" })} />`}
          ${remove ? html`<div></div>` : html`<div className="val"><span className="lead to">to</span>
            <${Select} value=${c.value} free=${true} mono=${true} options=${asOpts(values[c.field] || [])}
              placeholder=${c.field === "uom" ? "Choose new unit, e.g. KW or KVA" : "Choose or type the new value"}
              onChange=${v => setC({ value: v, target: "A" })} />
          </div>`}
          <button type="button" className="x" title="Remove change" onClick=${() => set({ changes: rule.changes.filter(x => x.id !== c.id) })}>×</button>
        </div>`;
      })}
      <div className="adds"><button type="button" className="btn ghost sm" onClick=${() => set({ changes: rule.changes.concat([newChange("A")]) })}>+ Add change</button></div>
      ${rule.changes.some(c => c.action !== "remove" && !c.value) && html`<div className="muted small"><span className="dot warn"></span> Choose a new value to preview the change.</div>`}</div>`}
    </div>`}

    ${!vkey && adv && html`<div className="card">
      <div className="card-head">
        <h2>Bill conditions</h2>
        <span className="grow"></span>
        <label className="muted small">Bills dated</label>
        <input className="inp date" type="date" value=${rule.dateFrom} onInput=${e => set({ dateFrom: e.target.value })} />
        <span className="muted small">to</span>
        <input className="inp date" type="date" value=${rule.dateTo} onInput=${e => set({ dateTo: e.target.value })} />
        <${Select} className="w-match" value=${rule.match} search=${false} options=${MATCH_OPTS} onChange=${v => set({ match: v })} />
      </div>
      ${!rule.conditions.length && html`<div className="muted small hint">No bill conditions: every bill in the date range qualifies.</div>`}
      <${Group} node=${rule} depth=${0} fieldList=${billFields} ctx=${ctx} defaultField=""
        onChange=${n => set({ conditions: n.conditions })} />
    </div>`}

    ${!vkey && adv && html`<div className="card">
      <div className="card-head"><h2>Lines on the same bill</h2>
        <span className="muted small">Each letter is one line on the bill. Its conditions must all match that one line.</span></div>
      ${rule.aliases.map(a => {
        const setA = p => set({ aliases: rule.aliases.map(x => x.id === a.id ? Object.assign({}, x, p) : x) });
        const fl = aliasFields(a.name).concat(billFields);
        return html`<div key=${a.id} className="alias">
          <div className="alias-head">
            <span className="badge">${a.name}</span>
            <${Select} className="w-mode" value=${a.mode} search=${false} options=${MODE_OPTS} onChange=${mode => {
              const nextAliases = rule.aliases.map(x => x.id === a.id ? Object.assign({}, x, { mode }) : x);
              set({ aliases: nextAliases,
                cross: mode === "not_exists" ? rule.cross.filter(keepFor(a.name)) : rule.cross,
                changes: mode === "not_exists" ? rule.changes.filter(x => x.target !== a.name) : rule.changes });
            }} />
            <span className="muted small">match</span>
            <${Select} className="w-sm" value=${a.match || "ALL"} search=${false} options=${GROUP_MATCH_OPTS} onChange=${v => setA({ match: v })} />
            <span className="grow"></span>
            <button type="button" className="btn ghost danger sm" onClick=${() => set({ aliases: rule.aliases.filter(x => x.id !== a.id),
              cross: rule.cross.filter(keepFor(a.name)), changes: rule.changes.filter(x => x.target !== a.name) })}>Remove ${a.name}</button>
          </div>
          <${Group} node=${a} depth=${0} fieldList=${fl} ctx=${ctx} defaultField=${a.name + ".code"}
            onChange=${n => setA({ conditions: n.conditions })} />
        </div>`;
      })}
      <div className="adds">
        ${rule.aliases.length < 4 && html`<button type="button" className="btn ghost" onClick=${addAlias}>+ Add line</button>`}
      </div>
    </div>`}

    ${!vkey && adv && (present.length > 1 || rule.cross.length > 0) && html`<div className="card">
      <div className="card-head"><h2>Compare lines</h2>
        <span className="muted small">Compare one line with another, for example A · Quantity equals B · Quantity.</span></div>
      ${rule.cross.map((c, i) => html`<${CondRow} key=${c.id} c=${c} lead=${i ? "AND" : "If"} fieldList=${crossFields} ctx=${ctx} fieldMode=${true}
        onChange=${nc => set({ cross: rule.cross.map(x => x.id === c.id ? nc : x) })}
        onRemove=${() => set({ cross: rule.cross.filter(x => x.id !== c.id) })} />`)}
      <div className="adds"><button type="button" className="btn ghost sm" onClick=${() => set({ cross: rule.cross.concat([Object.assign(newCond(), { mode: "field" })]) })}>+ Add comparison</button></div>
    </div>`}

    ${!vkey && adv && present.length > 0 && html`<div className="card">
      <div className="card-head"><h2>Changes to make</h2>
        <span className="pill">Preview only</span>
        <span className="muted small">Shown next to each matching line. Nothing is saved to UBM.</span></div>
      ${rule.changes.map(c => {
        const setC = p => set({ changes: rule.changes.map(x => x.id === c.id ? Object.assign({}, x, p) : x) });
        const remove = c.action === "remove";
        const others = present.filter(a => a.name !== c.target).map(a => a.name);
        return html`<div key=${c.id} className="row chg">
          <${Select} value=${c.action || "set"} search=${false} options=${ACTIONS} onChange=${v => setC({ action: v })} />
          <${Select} value=${c.target} search=${false} placeholder="Choose which line…"
            options=${present.map(a => ({ value: a.name, label: "Line " + a.name }))} onChange=${v => setC({ target: v })} />
          ${remove ? html`<div className="val chg-note muted small">${c.target ? (others.length ? "Keeps line " + others.join(", ") + "." : "The line is removed from the bill.") : "Choose which line to remove."}</div>`
            : html`<${Select} value=${c.field} search=${false} options=${CHANGE_FIELDS.map(f => ({ value: f.id, label: f.label }))}
            onChange=${v => setC({ field: v, value: "" })} />`}
          ${remove ? html`<div></div>` : html`<div className="val"><span className="lead to">to</span>
            <${Select} value=${c.value} free=${true} mono=${true} options=${asOpts(values[c.field] || [])}
              placeholder=${c.field === "uom" ? "Choose new unit, e.g. KW or KVA" : "Choose or type the new value"}
              onChange=${v => setC({ value: v })} />
          </div>`}
          <button type="button" className="x" title="Remove change" onClick=${() => set({ changes: rule.changes.filter(x => x.id !== c.id) })}>×</button>
        </div>`;
      })}
      <div className="adds"><button type="button" className="btn ghost sm" onClick=${() => set({ changes: rule.changes.concat([newChange(present[0].name)]) })}>+ Add change</button></div>
      ${rule.changes.some(c => !c.target) && html`<div className="muted small"><span className="dot warn"></span> Choose which line each change applies to.</div>`}
      ${rule.changes.some(c => c.target && c.action !== "remove" && !c.value) && html`<div className="muted small"><span className="dot warn"></span> Choose a new value to preview the change.</div>`}
    </div>`}

    ${!vkey && html`<div className="bar">
      <span className=${err ? "dot bad" : "dot"}></span>
      <span className=${err ? "err" : "muted"}>${err || (m.custName ? m.custName + " · " : "") + (count ? count + " condition" + (count === 1 ? "" : "s") + " set" : "No conditions yet")}</span>
      <span className="grow"></span>
      <button type="button" className="btn ghost" onClick=${() => setRule(Object.assign(blankRule(), { key: rule.key, dateFrom: rule.dateFrom, dateTo: rule.dateTo }))}>Clear all</button>
      <button type="button" className="btn ghost" onClick=${() => showSql ? setShowSql(false) : send("onPreview")}>${showSql ? "Hide SQL" : "Show SQL"}</button>
      <button type="button" className="btn primary" disabled=${running || !m.cust} onClick=${() => send("onRun")}>${running ? "Running…" : "Run query"}</button>
    </div>`}
    ${!vkey && showSql && sqlInfo.sql && html`<pre className="sql">${"-- Matching bills\n" + sqlInfo.sql + Object.keys(sqlInfo.obs || {}).map(k => "\n\n-- Matching lines " + k + "\n" + sqlInfo.obs[k]).join("")}</pre>`}

    ${!vkey && html`<${Results} res=${shownRes} running=${!!m.running} changes=${rule.changes} basic=${!adv} />`}
  </div>
  </div>`;
}

createRoot(document.getElementById("root")).render(html`<${App} />`);
